#requires -Version 5.1
# Generated by Prepare-Package.ps1. Upload the generated Detect-Installation.ps1 to Intune.
$ErrorActionPreference='Stop'
$ExpectedManifestHash='__MANIFEST_SHA256__'
try {
    $root=Join-Path ([Environment]::GetFolderPath('CommonApplicationData')) 'ClaudePolicyManager'
    $manifestPath=Join-Path $root 'PackageManifest.json'
    if ((Get-FileHash -LiteralPath $manifestPath -Algorithm SHA256).Hash.ToLowerInvariant() -cne $ExpectedManifestHash) {throw 'Assigned package/configuration differs.'}
    $manifest=Get-Content -LiteralPath $manifestPath -Raw | ConvertFrom-Json
    $modulePath=Join-Path $root 'PolicyEngine.psm1'
    if ((Get-FileHash -LiteralPath $modulePath -Algorithm SHA256).Hash.ToLowerInvariant() -cne $manifest.Files.'PolicyEngine.psm1') {throw 'Engine missing or altered.'}
    Import-Module $modulePath -Force -DisableNameChecking
    Assert-InstallationHealthy $root
    Write-Output "Detected Claude policy manager: $($manifest.ConfigurationId)."
    exit 0
} catch {
    $failureRecord=$_
    # Detection must emit NO success output on failure. Logging is best effort only.
    try {
        $logDir=Join-Path $env:ProgramData 'Microsoft\IntuneManagementExtension\Logs'
        if (-not (Test-Path -LiteralPath $logDir -PathType Container)) {$logDir=Join-Path $env:SystemRoot 'Logs'}
        $logPath=Join-Path $logDir 'ClaudePolicyManager-Detection.log'
        # Bound growth from repeated Intune detection runs.
        if ((Test-Path -LiteralPath $logPath) -and (Get-Item -LiteralPath $logPath).Length -gt 2097152) {
            Move-Item -LiteralPath $logPath -Destination ($logPath+'.1') -Force
        }
        $detail="[{0}] Not detected. Expected manifest: {1}; 64BitProcess={2}`r`n{3}`r`nPosition: {4}`r`nScript stack: {5}`r`n" -f [DateTime]::UtcNow.ToString('o'),$ExpectedManifestHash,[Environment]::Is64BitProcess,($failureRecord | Format-List * -Force | Out-String -Width 240),$failureRecord.InvocationInfo.PositionMessage,$failureRecord.ScriptStackTrace
        Add-Content -LiteralPath $logPath -Value $detail -Encoding UTF8 -ErrorAction Stop
    } catch { # A logging failure must never change the detection result.
    }
    exit 1
}
